-- BTD Macro — зашифрованный загрузчик v1
-- Этот файл не читается текстом: внутри лежит зашифрованный скрипт, расшифровывается он
-- только в момент запуска, здесь же, через loadstring. Исходник для правок — отдельный
-- читаемый файл у владельца, этот файл раздаётся друзьям и лежит в репозитории.
-- ЧЕСТНО: ключ расшифровки лежит в этом же файле ниже (иначе файл не смог бы сам себя запустить),
-- поэтому это защита от простого "открыл текстом/вставил в Pastebin и прочитал", а не от того,
-- кто специально достанет ключ из этого же файла или снимет код из памяти экзекьютора в момент
-- выполнения — это в принципе не останавливается никаким шифрованием на стороне клиента.
local _k = {209,166,106,48,172,186,9,59,108,241,5,140,103,253,34,7,43,79,220,130,47,65,177,233,187,98,255,214,93,254,29,72,27,81,205,237,81}
local _b = ""

local function _d(b64str, key)
    local B = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local rev = {}
    for i = 1, #B do rev[B:byte(i)] = i - 1 end
    local bytesOut = {}
    local bits, nbits = 0, 0
    for i = 1, #b64str do
        local v = rev[b64str:byte(i)]
        if v then
            bits = bits * 64 + v
            nbits = nbits + 6
            if nbits >= 8 then
                nbits = nbits - 8
                bytesOut[#bytesOut + 1] = bit32.rshift(bits, nbits) % 256
            end
        end
    end
    local klen = #key
    local chars = {}
    for i = 1, #bytesOut do
        chars[i] = string.char(bit32.bxor(bytesOut[i], key[((i - 1) % klen) + 1]))
    end
    return table.concat(chars)
end

local src = _d(_b, _k)
local fn, err = loadstring(src)
if not fn then
    warn("[BTD] не удалось разобрать расшифрованный скрипт: " .. tostring(err))
    return
end
fn()
